89	const insuranceValueList: Record<string, number> = {
90	  sword: 1000,
91	  amulet: 600,
92	  staff: 800,
93	  potion: 400,
94	  rune: 250,
95	  moonstone: 250,
96	};
97	
98	const CAP_MULTIPLIER = 2;
99	const DEDUCTIBLE = 100;
100	const HIGH_ENCHANTMENT_PAYOUT_THRESHOLD = 8;
101	const HIGH_ENCHANTMENT_PAYOUT_RATE = 0.5;
102	
103	const insuranceSum = (items: Item[]): number =>
104	  sumBy(items, (item) => insuranceValueList[item.type]);
105	
106	type Damage = { itemType: string; amount: number };
107	
108	const reimbursementFor = (damage: Damage, items: Item[]): number => {
109	  const insured = items.find((item) => item.type === damage.itemType);
110	  const reimbursable =
111	    (insured?.enchantment ?? 0) >= HIGH_ENCHANTMENT_PAYOUT_THRESHOLD
112	      ? damage.amount * HIGH_ENCHANTMENT_PAYOUT_RATE
113	      : damage.amount;
114	  return reimbursable - DEDUCTIBLE;
115	};
116	
117	type Incident = { cause: string; damages: Damage[] };
118	
119	type QuoteStep = { op: "quote"; items: Item[] };
120	type ClaimStep = { op: "claim"; policy: number; incident: Incident };
121	type Step = QuoteStep | ClaimStep;
122	type Scenario = { customer: Customer; steps: Step[] };
123	
124	type Policy = { items: Item[]; remainingCap: number };
125	type QuoteResult = { premium: number };
126	type ClaimResult = { payout: number; remainingCap: number };
127	type StepResult = QuoteResult | ClaimResult;
128	
129	export const runScenario = (scenario: Scenario): { results: StepResult[] } => {
130	  const policies: Record<number, Policy> = {};
131	  let quoteCount = 0;
132	
133	  const handleQuote = (step: QuoteStep, index: number): QuoteResult => {
134	    const isFollowUp = quoteCount > 0;
135	    quoteCount += 1;
136	    policies[index] = {
137	      items: step.items,
138	      remainingCap: insuranceSum(step.items) * CAP_MULTIPLIER,
139	    };
140	    return { premium: quotePremium(step.items, scenario.customer, isFollowUp) };
141	  };
142	
143	  const handleClaim = (step: ClaimStep): ClaimResult => {
144	    const policy = policies[step.policy];
145	    const payout = sumBy(step.incident.damages, (damage) =>
146	      reimbursementFor(damage, policy.items),
147	    );
148	    policy.remainingCap -= payout;
149	    return { payout, remainingCap: policy.remainingCap };
150	  };
151	
152	  const results = scenario.steps.map((step, index): StepResult =>
153	    step.op === "quote" ? handleQuote(step, index) : handleClaim(step),
154	  );
155	
156	  return { results };
157	};
